{"command":"python3 - <<'PY'
import csv, json, subprocess
from pathlib import Path

# Run checker to obtain actual status
raw = subprocess.check_output(['python3', 'check_revocation.py', '--format', 'json'], text=True)
check = json.loads(raw)

# Load employee names
employees = {}
with open('data/offboarding_list.csv', newline='') as f:
    for row in csv.DictReader(f):
        employees[row['employee_id']] = row['full_name']

system_labels = {
    'vpn': ('VPN Access', 'Corporate VPN'),
    'gitlab': ('GitLab Access', 'GitLab'),
    'wiki': ('Internal Wiki Access', 'Internal Wiki'),
}

by_emp = {eid: [] for eid in employees}
for p in check['privileges']:
    by_emp.setdefault(p['employee_id'], []).append(p)

employee_details = []
not_full = []
for eid, name in employees.items():
    privs = []
    all_revoked = True
    for p in by_emp.get(eid, []):
        privilege_name, system_name = system_labels.get(p['system'], (p['system'], p['system']))
        revoked = (p['status'] == 'revoked')
        if not revoked:
            all_revoked = False
        privs.append({
            'privilege_name': privilege_name,
            'system': system_name,
            'privilege_revoked': revoked,
        })
    # If expected privileges missing, insufficient/false. Here all are present.
    if len(privs) != 3:
        all_revoked = False
    if not all_revoked:
        not_full.append(eid)
    employee_details.append({
        'employee_id': eid,
        'employee_name': name,
        'privileges': privs,
        'all_privileges_revoked': all_revoked,
    })

successful = sum(1 for p in check['privileges'] if p['status'] == 'revoked')
total_privs = len(check['privileges'])
all_privs = successful == total_privs == 30 and len(employees) == 10

report = {
    'report_metadata': {
        'audit_timestamp': check['timestamp'],
        'auditor': 'pi coding agent',
        'report_version': '1.0',
    },
    'summary': {
        'total_employees_checked': len(employees),
        'total_privileges_checked': total_privs,
        'successfully_revoked_count': successful,
        'all_privileges_revoked': all_privs,
    },
    'employee_details': employee_details,
    'findings': {
        'employees_notfully_revoked': not_full,
    },
    'conclusion': 'privileges still not revoked: 28 of 30 privileges are revoked; emp_008 has VPN access active and emp_009 has GitLab access scheduled.',
}

Path('/testbed/revocation_report.json').write_text(json.dumps(report, indent=2) + '\n')
print(json.dumps(report['summary'], indent=2))
print('employees_notfully_revoked:', ', '.join(not_full))
